import assert from 'node:assert/strict';
import fs from 'node:fs';
import test from 'node:test';

// Structural acceptance check, paired with independently captured public/native
// single-source scalar controls in card-t-c/scalar-owner-red/. No widening of
// GROUP/HAVING/ORDER/set/IN/EXISTS admission is implied by this requirement.
const source=fs.readFileSync(new URL('../../src/internal/vdbe.ts',import.meta.url),'utf8');
const scalarOwner=source.slice(source.indexOf('function resolvedScalarSubqueryEmitter('),source.indexOf('function compileInnerTableSelect('));
test('linked scalar preparation delegates already-supported ordinary projection to SELECT producer and Mem destination',()=>{
 assert.match(scalarOwner,/compileInnerTableSelect\(/,
  'already-supported scalar projection still owns a parallel OpenRead/Rewind/Next loop instead of reusing the ordinary SELECT producer');
 assert.doesNotMatch(scalarOwner,/const success=|const value=compileExpressionTree\(bindResolvedExpression\(tree/, 'displaced scalar projection scan must not remain live');
 assert.match(scalarOwner,/scalarPrepared:true/, 'scalar LIMIT admission remains semantic-owner owned');
 assert.match(scalarOwner,/(?:destination:\s*|:)\{\s*kind:\s*['"]mem['"]/,
  'linked scalar preparation must hand the shared producer a Mem destination');
});

test('linked scalar aggregate delegates accumulator and Mem production to shared aggregate SELECT owner',()=>{
 assert.match(scalarOwner,/compileAggregateSelect\(/,
  'already-supported scalar aggregate still bypasses shared aggregate analysis/reset/finalization and SELECT destination production');
 assert.doesNotMatch(scalarOwner,/code:\s*['"]AggStep['"]|code:\s*['"]AggFinal['"]/,
  'scalar semantic preparation must not retain its independent accumulator scan');
});

